import redis
from fastapi import FastAPI, Header, HTTPException

r = redis.Redis(decode_responses=True)
app = FastAPI()

@app.post("/payments", status_code=201)
def create_payment(body: PaymentIn, idempotency_key: str = Header(...)):
    key = f"idem:payments:{idempotency_key}"

    saved = r.get(key)
    if saved and saved != "processing":
        return json.loads(saved)                     # retry: same answer, no new charge

    if not r.set(key, "processing", nx=True, ex=86400):
        raise HTTPException(409, "Same request is already being processed")

    try:
        result = charge_customer(body)               # runs only once per key
    except Exception:
        r.delete(key)                                # allow a real retry after failure
        raise
    r.set(key, json.dumps(result), ex=86400)
    return result

