import hashlib
import json
from fastapi import FastAPI, Header, HTTPException, Request, Response

app = FastAPI()

def etag_of(product: dict) -> str:
    raw = json.dumps(product, sort_keys=True, default=str).encode()
    return '"' + hashlib.sha256(raw).hexdigest()[:32] + '"'

@app.get("/api/v1/products/{pid}")
def get_product(pid: int, request: Request, response: Response):
    product = repo.get(pid)
    etag = etag_of(product)
    if request.headers.get("if-none-match") == etag:
        return Response(status_code=304, headers={"ETag": etag})   # client copy is still valid
    response.headers["ETag"] = etag
    response.headers["Cache-Control"] = "public, max-age=60"
    return product

@app.put("/api/v1/products/{pid}")
def update_product(pid: int, body: ProductIn, if_match: str = Header(...)):
    current = repo.get(pid)
    if if_match != etag_of(current):
        raise HTTPException(412, "This product was changed by someone else. Reload and try again.")
    return repo.update(pid, body)

