MAX_BATCH = 500

@app.post("/api/v1/customers/bulk")
def bulk_create(items: list[CustomerIn]):
    if len(items) > MAX_BATCH:
        raise HTTPException(413, f"Send at most {MAX_BATCH} customers per request")

    results = []
    for index, item in enumerate(items):
        try:
            customer = customers.create(item)
            results.append({"index": index, "status": 201, "id": customer.id})
        except DuplicateEmailError:
            results.append({"index": index, "status": 409, "error": "EMAIL_ALREADY_EXISTS"})

    failed = any(r["status"] >= 400 for r in results)
    return JSONResponse(status_code=207 if failed else 201, content={"results": results})

