import jwt
from argon2 import PasswordHasher
from argon2.exceptions import VerifyMismatchError
from fastapi import Depends, FastAPI, HTTPException, status
from fastapi.security import OAuth2PasswordBearer, OAuth2PasswordRequestForm

SECRET_KEY = settings.jwt_secret          # long random value from the environment
ALGORITHM = "HS256"
ph = PasswordHasher()                     # Argon2
oauth2_scheme = OAuth2PasswordBearer(tokenUrl="/api/v1/auth/token")
app = FastAPI()

UNAUTHORIZED = HTTPException(status.HTTP_401_UNAUTHORIZED, "Incorrect email or password",
                             headers={"WWW-Authenticate": "Bearer"})

def create_access_token(user_id: int) -> str:
    now = datetime.now(timezone.utc)
    claims = {"sub": str(user_id), "iat": now, "exp": now + timedelta(minutes=15), "type": "access"}
    return jwt.encode(claims, SECRET_KEY, algorithm=ALGORITHM)

@app.post("/api/v1/auth/token")
def login(form: OAuth2PasswordRequestForm = Depends()):
    user = users.get_by_email(form.username)
    try:
        if user is None:
            raise VerifyMismatchError()
        ph.verify(user.password_hash, form.password)
    except VerifyMismatchError:
        raise UNAUTHORIZED                # same message for unknown email and wrong password
    return {"access_token": create_access_token(user.id), "token_type": "bearer"}

def get_current_user(token: str = Depends(oauth2_scheme)):
    try:
        payload = jwt.decode(token, SECRET_KEY, algorithms=[ALGORITHM],
                             options={"require": ["exp", "sub"]})
    except jwt.InvalidTokenError:         # also covers ExpiredSignatureError
        raise HTTPException(401, "Invalid or expired token", headers={"WWW-Authenticate": "Bearer"})
    if payload.get("type") != "access":
        raise HTTPException(401, "Wrong token type")
    user = users.get(int(payload["sub"]))
    if user is None or not user.is_active:
        raise HTTPException(401, "User not found or disabled")
    return user

@app.get("/api/v1/me")
def me(user=Depends(get_current_user)):
    return {"id": user.id, "email": user.email}

import jwt
from fastapi import Depends, FastAPI, HTTPException, Security
from fastapi.security import OAuth2PasswordBearer, SecurityScopes

oauth2_scheme = OAuth2PasswordBearer(
    tokenUrl="/api/v1/auth/token",
    scopes={"orders:read": "Read orders", "orders:write": "Create and change orders"},
)
app = FastAPI()

def get_current_user(security_scopes: SecurityScopes, token: str = Depends(oauth2_scheme)):
    try:
        payload = jwt.decode(token, SECRET_KEY, algorithms=["HS256"], options={"require": ["exp", "sub"]})
    except jwt.InvalidTokenError:
        raise HTTPException(401, "Invalid token", headers={"WWW-Authenticate": "Bearer"})
    granted = set(payload.get("scope", "").split())
    missing = [s for s in security_scopes.scopes if s not in granted]
    if missing:
        raise HTTPException(403, f"Missing scope: {', '.join(missing)}")
    return users.get(int(payload["sub"]))

@app.get("/api/v1/orders/{order_id}")
def get_order(order_id: int, user=Security(get_current_user, scopes=["orders:read"])):
    order = orders.get(order_id)
    if order is None or (order.customer_id != user.id and user.role != "admin"):
        raise HTTPException(404, "Order not found")     # ownership check (404 hides existence)
    return order

